1	package transport
2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"io"
8		"net/http"
9		"strings"
10	
11		"github.com/entireio/cli/internal/entireclient/discovery"
12		"github.com/entireio/cli/internal/remotehelper/debuglog"
13	)
14	
15	// InfoRefs fetches the ref advertisement from the server. This is
16	// also the discovery entry point: the response's X-Entire-Replicas
17	// header refreshes the proxy's cached replica set, and every
18	// subsequent request in this invocation hits one of those replicas
19	// directly.
20	//
21	// Warm path: when the cache has replicas, they're tried with failover.
22	// If every cached replica fails we fall back to the cold path rather
23	// than surfacing the error — the cached set may be entirely stale
24	// (cluster resized, replicas moved) and the entry domain's LB will
25	// still route us to a live node.
26	//
27	// Cold path: probe the entry domain without auto-following 3xx. If it
28	// returns 307 + X-Entire-Replicas we adopt those replicas as the
29	// working set and run the warm-path failover instead of letting Go's
30	// HTTP client dial the redirect target — that matters when the
31	// redirect target's DNS or TCP is broken: failover rolls to the next
32	// replica instead of returning the dial error. When the redirect
33	// carries no replica header we fall back to following the redirect
34	// once. A direct 2xx is handled in place.
35	func (p *Proxy) InfoRefs(ctx context.Context, service string) (io.ReadCloser, error) {
36		suffix := "/info/refs?service=" + service
37	
38		var warmErr error
39		switch {
40		case len(p.nodes) > 0:
41			debuglog.Printf("info/refs warm path: trying %d cached replicas %v", len(p.nodes), p.nodes)
42			resp, err := p.doWithFailover(ctx, suffix, http.MethodGet, nil, nil)
43			if err == nil {
44				return p.handleInfoRefsResponse(resp)
45			}
46			if p.entryURL == "" {
47				return nil, fmt.Errorf("fetching info/refs: %w", err)
48			}
49			warmErr = err
50			debuglog.Printf("all cached replicas failed for info/refs, falling back to entry URL %s: %v", p.entryURL, err)
51		case p.entryURL == "":
52			return nil, errors.New("no replicas available and no entry URL configured")
53		default:
54			debuglog.Printf("info/refs cold path: hitting entry URL %s (LB will route or 307 to a hosting replica)", p.entryURL)
55		}
56	
57		body, err := p.coldInfoRefs(ctx, suffix, nil)
58		if err != nil && warmErr != nil {
59			return nil, errors.Join(fmt.Errorf("cached replicas: %w", warmErr), err)
60		}
61		return body, err
62	}
63	
64	// InfoRefsV2 is InfoRefs with Git-Protocol: version=2 added — same
65	// replica-failover / cold-path / discovery logic, but the server's v2
66	// capability advertisement is what gets returned instead of the v0/v1
67	// ref list.
68	func (p *Proxy) InfoRefsV2(ctx context.Context) (io.ReadCloser, error) {
69		suffix := "/info/refs?service=git-upload-pack"
70		setHeaders := func(req *http.Request) {
71			req.Header.Set("Git-Protocol", "version=2")
72		}
73	
74		var warmErr error
75		switch {
76		case len(p.nodes) > 0:
77			debuglog.Printf("v2 info/refs warm path: trying %d cached replicas %v", len(p.nodes), p.nodes)
78			resp, err := p.doWithFailover(ctx, suffix, http.MethodGet, nil, setHeaders)
79			if err == nil {
80				return p.handleInfoRefsResponse(resp)
81			}
82			if p.entryURL == "" {
83				return nil, fmt.Errorf("fetching v2 info/refs: %w", err)
84			}
85			warmErr = err
86			debuglog.Printf("all cached replicas failed for v2 info/refs, falling back to entry URL %s: %v", p.entryURL, err)
87		case p.entryURL == "":
88			return nil, errors.New("no replicas available and no entry URL configured")
89		default:
90			debuglog.Printf("v2 info/refs cold path: hitting entry URL %s (LB will route or 307 to a hosting replica)", p.entryURL)
91		}
92	
93		body, err := p.coldInfoRefs(ctx, suffix, setHeaders)
94		if err != nil && warmErr != nil {
95			return nil, errors.Join(fmt.Errorf("cached replicas: %w", warmErr), err)
96		}
97		return body, err
98	}
99	
100	// coldInfoRefs fetches info/refs via the entry domain without
101	// following redirects automatically. See InfoRefs for the rationale.
102	//
103	// Order of attempts when the entry domain returns 307 + X-Entire-Replicas:
104	//  1. doWithFailover across the advertised replicas.
105	//  2. If every advertised replica fails, follow the original Location
106	//     target once. This salvages the request when the header was stale
107	//     but the LB-picked node is still healthy.
108	//
109	// Persisting the replica set is gated on a successful response so a
110	// stale header can't pin a bad set in the on-disk cache.
111	func (p *Proxy) coldInfoRefs(ctx context.Context, suffix string, setHeaders func(*http.Request)) (io.ReadCloser, error) {
112		entryURL := strings.TrimSuffix(p.entryURL, "/") + p.path + suffix
113		resp, err := p.doGet(ctx, entryURL, p.noRedirectClient(), setHeaders)
114		if err != nil {
115			return nil, fmt.Errorf("fetching info/refs from entry domain: %w", err)
116		}
117	
118		if !isRedirect(resp.StatusCode) {
119			return p.handleInfoRefsResponse(resp)
120		}
121	
122		rs := discovery.ParseReplicas(resp.Header.Get("X-Entire-Replicas"))
123		location := resp.Header.Get("Location")
124		_ = resp.Body.Close()
125	
126		if len(rs) == 0 {
127			debuglog.Printf("entry domain redirect missing X-Entire-Replicas; falling back to redirect-following")
128			followed, err := p.doGet(ctx, entryURL, p.client, setHeaders)
129			if err != nil {
130				return nil, fmt.Errorf("fetching info/refs from entry domain: %w", err)
131			}
132			return p.handleInfoRefsResponse(followed)
133		}
134	
135		debuglog.Printf("entry domain redirected with %d replicas %v; failing over instead of following", len(rs), rs)
136		p.nodes = rs
137	
138		viaReplicas, err := p.doWithFailover(ctx, suffix, http.MethodGet, nil, setHeaders)
139		if err == nil {
140			return p.handleInfoRefsResponse(viaReplicas)
141		}
142	
143		if location == "" {
144			return nil, fmt.Errorf("fetching info/refs after entry-domain redirect: %w", err)
145		}
146		debuglog.Printf("all advertised replicas failed; trying redirect Location %s as last-ditch fallback: %v", location, err)
147		locResp, locErr := p.doGet(ctx, location, p.client, setHeaders)
148		if locErr != nil {
149			return nil, fmt.Errorf("fetching info/refs after entry-domain redirect: %w", errors.Join(err, locErr))
150		}
151		return p.handleInfoRefsResponse(locResp)
152	}
153	
154	// handleInfoRefsResponse refreshes the replica cache from the response
155	// and returns the body (or a typed HTTP error). The caller is
156	// responsible for closing the returned ReadCloser on success.
157	func (p *Proxy) handleInfoRefsResponse(resp *http.Response) (io.ReadCloser, error) {
158		p.refreshReplicas(resp)
159	
160		if resp.StatusCode != http.StatusOK {
161			body, readErr := io.ReadAll(io.LimitReader(resp.Body, 1024))
162			_ = resp.Body.Close()
163			var msg string
164			if readErr == nil {
165				msg = strings.TrimSpace(string(body))
166			}
167			if strings.HasPrefix(msg, "<") {
168				msg = ""
169			}
170			return nil, HTTPErrorMessage(resp.StatusCode, msg, p.ErrorBaseURL())
171		}
172		return resp.Body, nil
173	}
174	
175	// ServiceRPC sends data to a Git service endpoint and returns the
176	// response. The extraHeaders callbacks are invoked on each request to
177	// set additional headers (e.g. Git-Protocol, X-Entire-Push-Size).
178	func (p *Proxy) ServiceRPC(ctx context.Context, service string, body io.ReadSeeker, extraHeaders ...func(*http.Request)) (io.ReadCloser, error) {
179		suffix := "/" + service
180	
181		setHeaders := func(req *http.Request) {
182			req.Header.Set("Content-Type", fmt.Sprintf("application/x-%s-request", service))
183			req.Header.Set("Accept", fmt.Sprintf("application/x-%s-result", service))
184			for _, fn := range extraHeaders {
185				fn(req)
186			}
187		}
188	
189		resp, err := p.doWithFailover(ctx, suffix, http.MethodPost, body, setHeaders)
190		if err != nil {
191			return nil, fmt.Errorf("calling %s: %w", service, err)
192		}
193	
194		if resp.StatusCode != http.StatusOK {
195			respBody, readErr := io.ReadAll(io.LimitReader(resp.Body, 1024))
196			_ = resp.Body.Close()
197			var msg string
198			if readErr == nil {
199				msg = strings.TrimSpace(string(respBody))
200			}
201			if strings.HasPrefix(msg, "<") {
202				msg = ""
203			}
204			return nil, HTTPErrorMessage(resp.StatusCode, msg, p.ErrorBaseURL())
205		}
206	
207		return resp.Body, nil
208	}
209	
210	// HTTPErrorMessage returns a user-friendly error for non-200 HTTP
211	// responses. Exposed so handlers outside the transport package can
212	// produce the same shape.
213	func HTTPErrorMessage(statusCode int, serverMsg, baseURL string) error {
214		switch statusCode {
215		case http.StatusUnauthorized:
216			if serverMsg != "" {
217				return fmt.Errorf("authentication failed: %s", serverMsg)
218			}
219			return errors.New("authentication failed - please run 'entire login'")
220		case http.StatusNotFound:
221			if serverMsg != "" {
222				return errors.New(serverMsg)
223			}
224			return fmt.Errorf("repository not found: %s", baseURL)
225		default:
226			if serverMsg != "" {
227				return fmt.Errorf("server error (HTTP %d): %s", statusCode, serverMsg)
228			}
229			return fmt.Errorf("server error (HTTP %d)", statusCode)
230		}
231	}
